int num_x, num_y, max_n;
double min_diff_value = 1e9;
int final_num, final_den;

int calculate_lcm(int a, int b) {
    return a * b / __gcd(a, b);
}

int main() {
    cin >> num_x >> num_y >> max_n;
    if (num_y <= max_n) {
        while (__gcd(num_x, num_y) > 1) {
            int g = __gcd(num_x, num_y);
            num_x /= g;
            num_y /= g;
        }
        cout << num_x << "/" << num_y;
        return 0;
    }
    for (int i = 1; i <= max_n; i++) {
        int l = calculate_lcm(i, num_y);
        int w = num_x * (l / num_y);
        double diff1 = (double)(w - ((w / (l / i)) * (l / i))) / (double)l;
        if (min_diff_value > diff1) {
            min_diff_value = diff1;
            final_num = (w / (l / i));
            final_den = i;
        }
        int numerator = w + (l / i) - 1;
        int denominator = (l / i);
        double diff2 = (double)abs(w - (((numerator) / denominator) * denominator)) / (double)l;
        if (min_diff_value > diff2) {
            min_diff_value = diff2;
            final_num = ((numerator) / denominator);
            final_den = i;
        }
    }
    int g = __gcd(final_num, final_den);
    final_num /= g;
    final_den /= g;
    cout << final_num << "/" << final_den;
}
